'use client'

import { useEffect, useState } from 'react'
import { CheckCircle2 } from 'lucide-react'
import { StepStudioProfile } from './StepStudioProfile'
import { StepFirstLocation } from './StepFirstLocation'
import { StepFirstArtist } from './StepFirstArtist'
import { StepFirstService } from './StepFirstService'
import { StepBookingPageLive } from './StepBookingPageLive'

interface OnboardingWizardProps {
  studioId: string | null
  userId: string
}

const TOTAL_STEPS = 5
const STORAGE_KEY = 'inkos-onboarding-step'

const STEP_LABELS = [
  'Studio',
  'Location',
  'Artist',
  'Service',
  'Go live',
]

function StepIndicator({
  current,
  total,
}: {
  current: number
  total: number
}) {
  return (
    <div className="mb-8">
      <div className="flex items-center gap-1">
        {Array.from({ length: total }).map((_, i) => {
          const stepNum = i + 1
          const isDone = stepNum < current
          const isActive = stepNum === current

          return (
            <div key={i} className="flex flex-1 items-center">
              <div className="flex flex-col items-center">
                <div
                  aria-current={isActive ? 'step' : undefined}
                  className={[
                    'flex h-8 w-8 items-center justify-center rounded-full text-xs font-semibold transition-all',
                    isDone ? 'onboarding-step-done text-white' : '',
                    isActive ? 'onboarding-step-active text-white' : '',
                    !isDone && !isActive ? 'onboarding-step-future text-muted-foreground' : '',
                  ].join(' ')}
                >
                  {isDone ? (
                    <CheckCircle2 className="h-4 w-4" aria-hidden="true" />
                  ) : (
                    stepNum
                  )}
                </div>
                <span className="mt-1 hidden text-[10px] text-muted-foreground sm:block">
                  {STEP_LABELS[i]}
                </span>
              </div>

              {i < total - 1 && (
                <div
                  className={[
                    'mx-1 h-px flex-1',
                    isDone ? 'bg-emerald-500/60' : 'bg-border',
                  ].join(' ')}
                  aria-hidden="true"
                />
              )}
            </div>
          )
        })}

        <span className="ml-4 shrink-0 text-xs text-muted-foreground">
          Step {current} of {total}
        </span>
      </div>
    </div>
  )
}

export function OnboardingWizard({ studioId, userId }: OnboardingWizardProps) {
  const [startTime] = useState<number>(() => Date.now())

  const [currentStep, setCurrentStep] = useState<number>(() => {
    if (typeof window === 'undefined') return 1
    const saved = window.localStorage.getItem(STORAGE_KEY)
    const parsed = saved ? parseInt(saved, 10) : NaN
    return Number.isFinite(parsed) && parsed >= 1 && parsed <= TOTAL_STEPS
      ? parsed
      : 1
  })

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, String(currentStep))
  }, [currentStep])

  function goNext() {
    setCurrentStep((prev) => Math.min(prev + 1, TOTAL_STEPS))
  }

  function goBack() {
    setCurrentStep((prev) => Math.max(prev - 1, 1))
  }

  return (
    <div className="w-full overflow-hidden rounded-xl border border-border/50 bg-card shadow-[var(--shadow-soft-md)]">
      <div className="h-[3px] w-full bg-primary" />
      <div className="p-8">
        {/* InkOS wordmark */}
        <div className="mb-6 flex items-center gap-2">
          <div className="flex h-6 w-6 items-center justify-center rounded bg-primary">
            <span className="text-[10px] font-bold text-primary-foreground">IO</span>
          </div>
          <span className="text-sm font-semibold tracking-tight">InkOS</span>
        </div>

        <StepIndicator current={currentStep} total={TOTAL_STEPS} />

        {currentStep === 1 && (
          <StepStudioProfile studioId={studioId} onNext={goNext} />
        )}
        {currentStep === 2 && (
          <StepFirstLocation studioId={studioId} onNext={goNext} onBack={goBack} />
        )}
        {currentStep === 3 && (
          <StepFirstArtist
            studioId={studioId}
            userId={userId}
            onNext={goNext}
            onBack={goBack}
          />
        )}
        {currentStep === 4 && (
          <StepFirstService studioId={studioId} onNext={goNext} onBack={goBack} />
        )}
        {currentStep === 5 && (
          <StepBookingPageLive
            studioId={studioId}
            startTime={startTime}
            onBack={goBack}
          />
        )}
      </div>
    </div>
  )
}

'use client'

import { useState } from 'react'
import { useForm } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'
import { z } from 'zod'
import { toast } from 'sonner'
import { createClient } from '@/lib/supabase/client'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'

const step2Schema = z.object({
  locationName: z.string().min(2, 'At least 2 characters').max(60),
  address: z.string().min(5, 'Enter a street address'),
  city: z.string().min(2, 'Required'),
  state: z.string().min(2, 'Required'),
  country: z.string().min(2, 'Required'),
  zip: z.string().min(3, 'Required'),
  phone: z.string().optional(),
})

type Step2Values = z.infer<typeof step2Schema>

interface StepFirstLocationProps {
  studioId: string | null
  onNext: () => void
  onBack: () => void
}

export function StepFirstLocation({
  studioId,
  onNext,
  onBack,
}: StepFirstLocationProps) {
  const supabase = createClient()
  const [saving, setSaving] = useState(false)

  const {
    register,
    handleSubmit,
    formState: { errors },
  } = useForm<Step2Values>({
    resolver: zodResolver(step2Schema),
    defaultValues: {
      locationName: 'Main Studio',
      country: 'United States',
    },
  })

  async function onSubmit(data: Step2Values) {
    setSaving(true)
    try {
      if (!studioId) throw new Error('No studio found')

      const { error } = await supabase.from('locations').insert({
        studio_id: studioId,
        name: data.locationName,
        address: data.address,
        city: data.city,
        state: data.state,
        country: data.country,
        zip: data.zip,
        phone: data.phone ?? null,
      })
      if (error) throw error

      onNext()
    } catch (err) {
      toast.error(
        `Couldn't save — ${err instanceof Error ? err.message : 'Unknown error'}`,
      )
    } finally {
      setSaving(false)
    }
  }

  return (
    <form onSubmit={handleSubmit(onSubmit)} className="space-y-5">
      <div>
        <h2 className="text-xl font-bold tracking-tight">
          Where are you located?
        </h2>
        <p className="mt-1 text-sm text-muted-foreground">
          You can add more locations later
        </p>
      </div>

      <div className="space-y-1.5">
        <Label htmlFor="locationName">
          Location name <span className="text-destructive">*</span>
        </Label>
        <Input
          id="locationName"
          placeholder="Main Studio"
          {...register('locationName')}
          aria-invalid={!!errors.locationName}
        />
        {errors.locationName && (
          <p role="alert" className="text-xs text-destructive">{errors.locationName.message}</p>
        )}
      </div>

      <div className="space-y-1.5">
        <Label htmlFor="address">
          Street address <span className="text-destructive">*</span>
        </Label>
        <Input
          id="address"
          autoComplete="street-address"
          {...register('address')}
          aria-invalid={!!errors.address}
        />
        {errors.address && (
          <p role="alert" className="text-xs text-destructive">{errors.address.message}</p>
        )}
      </div>

      <div className="grid grid-cols-2 gap-3">
        <div className="space-y-1.5">
          <Label htmlFor="city">
            City <span className="text-destructive">*</span>
          </Label>
          <Input
            id="city"
            autoComplete="address-level2"
            {...register('city')}
            aria-invalid={!!errors.city}
          />
          {errors.city && (
            <p role="alert" className="text-xs text-destructive">{errors.city.message}</p>
          )}
        </div>
        <div className="space-y-1.5">
          <Label htmlFor="state">
            State <span className="text-destructive">*</span>
          </Label>
          <Input
            id="state"
            autoComplete="address-level1"
            {...register('state')}
            aria-invalid={!!errors.state}
          />
          {errors.state && (
            <p role="alert" className="text-xs text-destructive">{errors.state.message}</p>
          )}
        </div>
      </div>

      <div className="grid grid-cols-2 gap-3">
        <div className="space-y-1.5">
          <Label htmlFor="country">
            Country <span className="text-destructive">*</span>
          </Label>
          <Input
            id="country"
            autoComplete="country-name"
            {...register('country')}
            aria-invalid={!!errors.country}
          />
          {errors.country && (
            <p role="alert" className="text-xs text-destructive">{errors.country.message}</p>
          )}
        </div>
        <div className="space-y-1.5">
          <Label htmlFor="zip">
            Zip <span className="text-destructive">*</span>
          </Label>
          <Input
            id="zip"
            autoComplete="postal-code"
            {...register('zip')}
            aria-invalid={!!errors.zip}
          />
          {errors.zip && (
            <p role="alert" className="text-xs text-destructive">{errors.zip.message}</p>
          )}
        </div>
      </div>

      <div className="space-y-1.5">
        <Label htmlFor="phone">Phone (optional)</Label>
        <Input
          id="phone"
          type="tel"
          autoComplete="tel"
          {...register('phone')}
        />
      </div>

      <div className="flex items-center justify-between pt-2">
        <Button type="button" variant="ghost" onClick={onBack}>
          ← Back
        </Button>
        <Button type="submit" disabled={saving}>
          {saving ? 'Saving...' : 'Continue →'}
        </Button>
      </div>
    </form>
  )
}

'use client'

import { useState } from 'react'
import { useForm } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'
import { z } from 'zod'
import { toast } from 'sonner'
import { createClient } from '@/lib/supabase/client'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { cn } from '@/lib/utils'

const SPECIALTY_OPTIONS = [
  'Blackwork',
  'Watercolor',
  'Traditional',
  'Neo-trad',
  'Realism',
  'Geometric',
  'Minimalist',
  'Portraits',
  'Script',
  'Cover-up',
]

const step3Schema = z.object({
  artistName: z.string().min(2, 'At least 2 characters').max(80),
  artistEmail: z
    .string()
    .email('Enter a valid email')
    .optional()
    .or(z.literal('')),
  specialties: z.array(z.string()).optional(),
})

type Step3Values = z.infer<typeof step3Schema>

interface StepFirstArtistProps {
  studioId: string | null
  userId: string
  onNext: () => void
  onBack: () => void
}

export function StepFirstArtist({
  studioId,
  userId,
  onNext,
  onBack,
}: StepFirstArtistProps) {
  const supabase = createClient()
  const [saving, setSaving] = useState(false)
  const [selectedSpecialties, setSelectedSpecialties] = useState<string[]>([])

  const {
    register,
    handleSubmit,
    formState: { errors },
  } = useForm<Step3Values>({
    resolver: zodResolver(step3Schema),
  })

  function toggleSpecialty(specialty: string) {
    setSelectedSpecialties((prev) =>
      prev.includes(specialty)
        ? prev.filter((s) => s !== specialty)
        : [...prev, specialty],
    )
  }

  async function onSubmit(data: Step3Values) {
    if (!studioId) {
      toast.error("Couldn't save — No studio found")
      return
    }

    setSaving(true)
    try {
      // Sprint 1: Store artist in profiles + studio_members (artists table is Sprint 2)
      // Update the profile name if not set
      await supabase
        .from('profiles')
        .update({ full_name: data.artistName })
        .eq('id', userId)

      // Upsert studio_member record (already exists from signup trigger, but ensure role is correct)
      const { error: memberError } = await supabase
        .from('studio_members')
        .upsert(
          {
            studio_id: studioId,
            user_id: userId,
            role: 'owner',
          },
          { onConflict: 'studio_id,user_id' },
        )
      if (memberError) throw memberError

      // Store specialties in localStorage for Sprint 2 migration
      if (selectedSpecialties.length > 0) {
        localStorage.setItem(
          'inkos-onboarding-specialties',
          JSON.stringify(selectedSpecialties),
        )
      }
      if (data.artistEmail) {
        localStorage.setItem('inkos-onboarding-artist-email', data.artistEmail)
      }

      onNext()
    } catch (err) {
      toast.error(
        `Couldn't save — ${err instanceof Error ? err.message : 'Unknown error'}`,
      )
    } finally {
      setSaving(false)
    }
  }

  return (
    <form onSubmit={handleSubmit(onSubmit)} className="space-y-5">
      <div>
        <h2 className="text-xl font-bold tracking-tight">
          Add your first artist
        </h2>
        <p className="mt-1 text-sm text-muted-foreground">
          That&#39;s probably you
        </p>
      </div>

      <div className="space-y-1.5">
        <Label htmlFor="artistName">
          Full name <span className="text-destructive">*</span>
        </Label>
        <Input
          id="artistName"
          autoComplete="name"
          {...register('artistName')}
          aria-invalid={!!errors.artistName}
        />
        {errors.artistName && (
          <p role="alert" className="text-xs text-destructive">
            {errors.artistName.message}
          </p>
        )}
      </div>

      <div className="space-y-1.5">
        <Label htmlFor="artistEmail">Artist email (for invite)</Label>
        <Input
          id="artistEmail"
          type="email"
          autoComplete="email"
          {...register('artistEmail')}
          aria-invalid={!!errors.artistEmail}
        />
        {errors.artistEmail && (
          <p role="alert" className="text-xs text-destructive">
            {errors.artistEmail.message}
          </p>
        )}
        <p className="text-xs text-muted-foreground">
          They&#39;ll get a login invite after setup
        </p>
      </div>

      <div className="space-y-2">
        <Label>Specialties (optional)</Label>
        <div className="flex flex-wrap gap-2">
          {SPECIALTY_OPTIONS.map((specialty) => {
            const selected = selectedSpecialties.includes(specialty)
            return (
              <button
                key={specialty}
                type="button"
                onClick={() => toggleSpecialty(specialty)}
                className={cn(
                  'h-7 rounded-full border px-3 text-xs transition-colors',
                  selected
                    ? 'border-primary/30 bg-primary/15 text-primary'
                    : 'border-border bg-transparent text-muted-foreground hover:border-border/80 hover:text-foreground',
                )}
              >
                {specialty}
                {selected && <span className="ml-1">×</span>}
              </button>
            )
          })}
        </div>
      </div>

      <div className="flex items-center justify-between pt-2">
        <Button type="button" variant="ghost" onClick={onBack}>
          ← Back
        </Button>
        <Button type="submit" disabled={saving}>
          {saving ? 'Saving...' : 'Continue →'}
        </Button>
      </div>
    </form>
  )
}

