import { slugify } from '@/lib/utils'

const bodySchema = z.object({
  email: z.string().email('Enter a valid email'),
  password: z.string().min(8, 'Use 8 or more characters'),
  studioName: z.string().min(2, 'Studio name must be at least 2 characters').max(60),
})

export async function POST(request: NextRequest) {
  // Rate limit by IP
  const ip = getClientIp(request)

  const { success, limit, remaining } = await signupRatelimit.limit(ip)
  if (!success) {
    return new Response('Too many signup attempts. Try again later.', {
      status: 429,
      headers: {
        'Retry-After': '60',
        'X-RateLimit-Limit': String(limit),
        'X-RateLimit-Remaining': '0',
      },
    })
  }

  // Validate body
  const raw = await request.json().catch(() => null)
  const parsed = bodySchema.safeParse(raw)
  if (!parsed.success) {
    return Response.json({ error: parsed.error.format() }, { status: 400 })
  }

  const admin = createServiceRoleClient()

  // Use admin.createUser — no email sent, no rate limit. Safe because the user just
  // proved ownership by choosing a password. Re-enable email verification later via
  // a proper check-your-inbox flow once SMTP is wired up.
  const { data: userData, error: createError } = await admin.auth.admin.createUser({
    email: parsed.data.email,
    password: parsed.data.password,
    email_confirm: true,
    user_metadata: {
      studio_name: parsed.data.studioName,
      full_name: parsed.data.studioName,
    },
  })

  if (createError) {
    logger.warn({ ip, errorCode: createError.status, message: createError.message }, 'auth.signup.failed')
    return Response.json(
      { error: createError.message },
      {
        status: 400,
        headers: {
          'X-RateLimit-Limit': String(limit),
          'X-RateLimit-Remaining': String(remaining),
        },
      },
    )
  }

  const userId = userData.user?.id
  logger.info({ userId }, 'auth.signup.success')

  // Create studio + owner membership using service-role client (bypasses RLS).
  // The handle_new_user trigger only creates profiles — we own studio provisioning here.
  if (userId) {
    try {
      const baseSlug = slugify(parsed.data.studioName) || 'studio'
      const slug = `${baseSlug}-${userId.slice(0, 6)}`

      const { data: studio, error: studioError } = await admin
        .from('studios')
        .insert({ name: parsed.data.studioName, slug })
        .select('id')
        .single()

      if (studioError) throw studioError

      const { error: memberError } = await admin
        .from('studio_members')
        .insert({ studio_id: studio.id, user_id: userId, role: 'owner' })

      if (memberError) throw memberError

      logger.info({ userId, studioId: studio.id }, 'auth.signup.studio_provisioned')
    } catch (err) {
      logger.error({ userId, err }, 'auth.signup.studio_provision_failed')
      // Non-fatal — user can still sign in and complete onboarding
    }
  }

  return Response.json({ ok: true })
}

