'use client'

import { useMemo } from 'react'
import {
  Sidebar,
  SidebarContent,
  SidebarHeader,
} from '@/components/ui/sidebar'
import { SidebarNavGroup } from '@/components/app/sidebar/SidebarNavGroup'
import { SidebarUserFooter } from '@/components/app/sidebar/SidebarUserFooter'
import { APP_NAV, type NavRole } from '@/components/app/sidebar/nav-config'
import type { PlanTier } from '@/lib/billing/feature-gate'

interface AppSidebarProps {
  plan: PlanTier
  user: {
    name: string
    email: string
    avatarUrl?: string | null
  }
  studioName: string
  studioLogoUrl?: string | null
  role: NavRole
  locationCount: number
  /** Serialized from server — Set<string> → JSON array → passed as prop */
  permissionKeys?: string[]
}

export function AppSidebar({
  plan,
  user,
  studioName,
  studioLogoUrl,
  role,
  locationCount,
  permissionKeys = [],
}: AppSidebarProps) {
  const permissions = useMemo(() => new Set(permissionKeys), [permissionKeys])

  const navGroups = useMemo(() => {
    return APP_NAV
      .filter((group) => !(group.condition === 'multi-location' && locationCount <= 1))
      .map((group) => ({
        ...group,
        items: group.items.filter((item) => {
          if (!item.requiredRoles.includes(role)) return false
          if (item.requiredPermission && !permissions.has(item.requiredPermission)) return false
          return true
        }),
      }))
      .filter((group) => group.items.length > 0)
  }, [role, locationCount, permissions])

  return (
    <Sidebar collapsible="icon">
      <SidebarHeader className="border-b border-sidebar-border px-3 py-3.5">
        <div className="flex items-center gap-2.5 group-data-[collapsible=icon]:justify-center">
          {studioLogoUrl ? (
            // eslint-disable-next-line @next/next/no-img-element
            <img
              src={studioLogoUrl}
              alt={studioName}
              className="h-8 w-8 rounded-md object-cover ring-1 ring-primary/30 shadow-[var(--shadow-soft)]"
            />
          ) : (
            <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-md bg-primary ring-1 ring-primary/20 shadow-[var(--shadow-soft)]">
              <span className="text-[11px] font-bold tracking-tight text-primary-foreground">
                IO
              </span>
            </div>
          )}
          <div className="flex min-w-0 flex-col group-data-[collapsible=icon]:hidden">
            <span className="text-sm font-bold leading-tight tracking-tighter text-sidebar-foreground">
              InkOS
            </span>
            <span className="max-w-[148px] truncate text-[11px] text-muted-foreground/70">
              {studioName}
            </span>
          </div>
        </div>
      </SidebarHeader>

      <SidebarContent>
        {navGroups.map((group) => (
          <SidebarNavGroup key={group.label} group={group} plan={plan} />
        ))}
      </SidebarContent>

      <SidebarUserFooter user={user} studioName={studioName} role={role} />
    </Sidebar>
  )
}

'use client'

import { usePathname } from 'next/navigation'
import Link from 'next/link'
import {
  SidebarGroup,
  SidebarGroupLabel,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
} from '@/components/ui/sidebar'
import { Badge } from '@/components/ui/badge'
import type { NavGroup } from '@/components/app/sidebar/nav-config'
import { hasFeature } from '@/lib/billing/feature-gate'
import type { PlanTier } from '@/lib/billing/feature-gate'

interface SidebarNavGroupProps {
  group: NavGroup
  plan: PlanTier
}

export function SidebarNavGroup({ group, plan }: SidebarNavGroupProps) {
  const pathname = usePathname()

  return (
    <SidebarGroup>
      <SidebarGroupLabel className="mb-0.5 px-3 text-[10px] font-semibold uppercase tracking-widest text-muted-foreground/40 group-data-[collapsible=icon]:hidden">
        {group.label}
      </SidebarGroupLabel>
      <SidebarMenu>
        {group.items.map((item) => {
          const isActive =
            pathname === item.href || pathname.startsWith(item.href + '/')

          const isGated =
            !!item.requiredPlan &&
            !!item.featureKey &&
            !hasFeature(plan, item.featureKey)

          return (
            <SidebarMenuItem key={item.href}>
              <SidebarMenuButton
                render={<Link href={item.href} />}
                isActive={isActive}
                className="h-9 gap-2.5 rounded-md px-3 text-[13px] font-medium text-sidebar-foreground/70 transition-colors hover:bg-sidebar-accent/60 hover:text-sidebar-foreground"
                tooltip={item.label}
              >
                <item.icon
                  className="!h-[17px] !w-[17px] shrink-0 opacity-60"
                  aria-hidden="true"
                />
                <span className="group-data-[collapsible=icon]:hidden">
                  {item.label}
                </span>
                {isGated && (
                  <Badge className="ml-auto h-4 bg-primary/15 px-1.5 py-0 text-[9px] text-primary border-primary/20 group-data-[collapsible=icon]:hidden">
                    Pro
                  </Badge>
                )}
                {item.badge && !isGated && (
                  <Badge className="ml-auto h-4 bg-emerald-500/15 px-1.5 py-0 text-[9px] text-emerald-500 border-emerald-500/20 group-data-[collapsible=icon]:hidden">
                    {item.badge === 'new' ? 'New' : 'Beta'}
                  </Badge>
                )}
              </SidebarMenuButton>
            </SidebarMenuItem>
          )
        })}
      </SidebarMenu>
    </SidebarGroup>
  )
}

